#!/bin/bash
# PreToolUse (Edit|Write|MultiEdit): blocks hand edits to generated files, which the next
# regeneration would silently revert. Exits 0 (allow) for everything else.
input=$(cat)
file=$(printf '%s' "$input" | jq -r '.tool_input.file_path // empty' 2>/dev/null)
[ -z "$file" ] && exit 0
case "$file" in
  */apps/docs/src/styles/theme.css)
    reason="apps/docs/src/styles/theme.css is generated from packages/design/src/tokens.ts. Change the tokens (they mirror apps/web/app/app.css, and packages/design's tests hold the two together), then run \`pnpm sync:theme\`. Hand-written docs styling goes in apps/docs/src/styles/brand.css." ;;
  */worker-configuration.d.ts)
    reason="worker-configuration.d.ts is generated by \`wrangler types\`. Change the app's wrangler.jsonc, then run \`pnpm --filter @orderloop/<engine|web> types\`." ;;
  *) exit 0 ;;
esac
jq -cn --arg r "$reason" '{hookSpecificOutput:{hookEventName:"PreToolUse", permissionDecision:"deny", permissionDecisionReason:$r}}'
exit 0
